<?php

declare(strict_types=1);

namespace Bjanczak\FilamentFlexFields\Support;

/**
 * Pinned Whisper / ONNX browser runtime (opt-in; not shipped in the Composer package).
 *
 * Hashes cover the browser bundle and its matching ONNX MJS/WASM source files.
 * Regenerated by `node scripts/build-whisper-runtime.mjs` when upgrading transformers.
 */
final class WhisperRuntimeManifest
{
    public const PACKAGE = '@huggingface/transformers';

    public const VERSION = '4.3.2';

    public const ONNX_VERSION = '1.31.0-dev.20260914-8d85527a0';

    public const INSTALL_COMMAND = 'php artisan fff:whisper:install';

    /**
     * Runtime files published to public/filament-flex-fields-assets/whisper/.
     * Source maps are intentionally excluded from customer installs.
     *
     * @var array<string, string> filename => sha256 hex
     */
    public const FILES = [
        'transformers.min.js' => '8b5a3171f8876bab2b1820a7d65eb87628e3d30bb5ea85b9dd398e76eb34decb',
        'ort-wasm-simd-threaded.mjs' => 'c57ca56328877353a575e51bbca6f18450027d6c9bf2307a2cb2c41363b4de9f',
        'ort-wasm-simd-threaded.wasm' => '06ba057753da3847e4c24f02d91ab133455b0817c69a44993a9a53a2146df9e3',
    ];

    /**
     * @return list<string>
     */
    public static function filenames(): array
    {
        return array_keys(self::FILES);
    }

    public static function sha256(string $filename): ?string
    {
        return self::FILES[$filename] ?? null;
    }

    public static function downloadUrl(string $filename): string
    {
        if (! isset(self::FILES[$filename])) {
            throw new \InvalidArgumentException("Unknown Whisper runtime file [{$filename}].");
        }

        return sprintf(
            'https://cdn.jsdelivr.net/npm/%s@%s/dist/%s',
            $filename === 'transformers.min.js' ? self::PACKAGE : 'onnxruntime-web',
            $filename === 'transformers.min.js' ? self::VERSION : self::ONNX_VERSION,
            $filename,
        );
    }

    /**
     * @return array{package: string, version: string, files: array<string, string>}
     */
    public static function toArray(): array
    {
        return [
            'package' => self::PACKAGE,
            'version' => self::VERSION,
            'files' => self::FILES,
        ];
    }
}
